package scaffold

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// _outDir is where projects are generated by default, relative to the template's root.
const _outDir = "scaffold/out"

// ErrMatrixFailed is a matrix run in which at least one preset failed its check.
var ErrMatrixFailed = errors.New("a preset failed its check")

// ErrNoTemplate is a directory with no scaffold manifest above it.
var ErrNoTemplate = errors.New("not inside the template (no " + ManifestPath + " above)")

// Command is one `make scaffold` run.
type Command struct {
	// Source is the template's root; empty means the one above the working directory.
	Source  string
	Preset  string
	With    []string
	Without []string
	// Name names the project and its directory under scaffold/out; it defaults to the preset's id,
	// "custom" once features are added or removed, or "everything".
	Name string
	// Module is the generated project's module path; empty keeps the template's.
	Module string
	// Out overrides <OutBase>/<name>.
	Out string
	// OutBase is the directory projects are generated into; empty means the template's
	// scaffold/out.
	OutBase string
	Force   bool
	NoRegen bool
	// Check runs `make pre-commit` in the generated project once it is regenerated.
	Check bool
	// Then is a command run in the generated project once it is regenerated (after Check):
	// `make scaffold-dev` uses it for `make dev` on other ports.
	Then string
}

// FindRoot returns the nearest directory at or above dir that holds the scaffold manifest.
func FindRoot(dir string) (string, error) {
	dir, err := filepath.Abs(dir)
	if err != nil {
		return "", fmt.Errorf("scaffold - FindRoot - filepath.Abs: %w", err)
	}

	for {
		if _, err := os.Stat(filepath.Join(dir, filepath.FromSlash(ManifestPath))); err == nil {
			return dir, nil
		}

		parent := filepath.Dir(dir)
		if parent == dir {
			return "", ErrNoTemplate
		}

		dir = parent
	}
}

// Run generates the project and, unless NoRegen is set, regenerates its generated code with run.
func (c *Command) Run(ctx context.Context, stdout io.Writer, run Runner) error {
	root, m, keep, err := c.resolve()
	if err != nil {
		return err
	}

	out := c.OutDir(root)

	report, err := Generate(ctx, &Options{
		Manifest: m, Keep: keep, Source: root, Out: out, Module: c.Module, Force: c.Force,
	})
	if err != nil {
		return err
	}

	if err := gitInit(ctx, out); err != nil {
		return err
	}

	_, _ = fmt.Fprintf(stdout, "Generated %s: %d files kept, %d removed (features: %s)\n",
		display(root, out), report.Kept, report.Removed, strings.Join(keep.IDs(), ", "))

	if c.NoRegen {
		return nil
	}

	if err := Regenerate(ctx, m, keep, out, run); err != nil {
		return err
	}

	return c.after(ctx, stdout, run, root, out)
}

// after runs the check and the Then command in the regenerated project.
func (c *Command) after(ctx context.Context, stdout io.Writer, run Runner, root, out string) error {
	if c.Check {
		if err := run.Run(ctx, out, "make pre-commit"); err != nil {
			return fmt.Errorf("scaffold - check failed in %s: %w", display(root, out), err)
		}

		_, _ = fmt.Fprintf(stdout, "Checked %s: make pre-commit passed\n", display(root, out))
	}

	if c.Then != "" {
		if err := run.Run(ctx, out, c.Then); err != nil {
			return fmt.Errorf("scaffold - %q failed in %s: %w", c.Then, display(root, out), err)
		}
	}

	return nil
}

// resolve finds the template, loads its manifest and resolves the selection.
func (c *Command) resolve() (root string, m *Manifest, keep Set, err error) {
	root = c.Source
	if root == "" {
		if root, err = FindRoot("."); err != nil {
			return "", nil, Set{}, err
		}
	}

	m, err = Load(filepath.Join(root, filepath.FromSlash(ManifestPath)))
	if err != nil {
		return "", nil, Set{}, err
	}

	keep, err = m.Resolve(Selection{Preset: c.Preset, With: c.With, Without: c.Without})
	if err != nil {
		return "", nil, Set{}, err
	}

	return root, m, keep, nil
}

// OutDir is where Run writes the project for the template at root.
func (c *Command) OutDir(root string) string {
	if c.Out != "" {
		return c.Out
	}

	base := c.OutBase
	if base == "" {
		base = filepath.Join(root, filepath.FromSlash(_outDir))
	}

	return filepath.Join(base, c.name())
}

// Display shows a path relative to the template's root when it is inside it.
func Display(root, path string) string {
	return display(root, path)
}

func (c *Command) name() string {
	switch {
	case c.Name != "":
		return c.Name
	case len(c.With) > 0 || len(c.Without) > 0:
		return CustomPreset
	case c.Preset != "":
		return c.Preset
	default:
		return "everything"
	}
}

// display shows out relative to the template's root when it is inside it.
func display(root, out string) string {
	if rel, err := filepath.Rel(root, out); err == nil && !strings.HasPrefix(rel, "..") {
		return filepath.ToSlash(rel)
	}

	return out
}

// gitInit makes out a git repository of its own, so tools in it read its .gitignore rather than
// the template's (which ignores scaffold/out).
func gitInit(ctx context.Context, out string) error {
	cmd := exec.CommandContext(ctx, "git", "init", "--quiet")
	cmd.Dir = out

	if b, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("scaffold - gitInit - git init: %w: %s", err, b)
	}

	return nil
}

// Matrix generates and checks every preset of the template at root, then prints a pass/fail line
// per preset. It keeps going after a failure and returns ErrMatrixFailed if any preset failed.
func Matrix(ctx context.Context, root string, stdout io.Writer, run Runner) error {
	m, err := Load(filepath.Join(root, filepath.FromSlash(ManifestPath)))
	if err != nil {
		return err
	}

	results := make([]string, 0, len(m.Presets))
	failed := false

	for _, p := range m.Presets {
		cmd := Command{Source: root, Preset: p.ID, Force: true, Check: true}

		status := "PASS"
		if err := cmd.Run(ctx, stdout, run); err != nil {
			status, failed = "FAIL", true

			_, _ = fmt.Fprintf(stdout, "scaffold-matrix: %s: %v\n", p.ID, err)
		}

		results = append(results, fmt.Sprintf("%s  %s", status, p.ID))
	}

	_, _ = fmt.Fprintf(stdout, "\nscaffold-matrix:\n  %s\n", strings.Join(results, "\n  "))

	if failed {
		return ErrMatrixFailed
	}

	return nil
}
